-- ==== part 10_r1_authorization_verdict.sql (blob 6e4ebfc4eb19807b8b0a493c8169313d66c9a1fc): its own begin; / commit; removed, nothing else changed ====
-- G5 SOURCE CANDIDATE (2026-10-19, Issue #320 G5-01 task 3). NOT in supabase/migrations/. Never apply to a managed or production database without
-- an independent focused Codex Sol (high) review of this file, the G5 担当ちゃ's acceptance and the owner's explicit production approval.
--
-- The G5 authorization verdict for POSTONA, as SQL (contract: docs/common-account/g5-02-authorization-verdict-rpc-preflight.md §3-§4; wire:
-- docs/common-account/g5-01-postona-entitlement-auth-boundary.md §4; reference: supabase/candidates/common_account_postona_authz/):
--
--   R1  public.common_account_authorization_verdict(p_app text, p_feature text, p_brand_id text) -> jsonb       EXECUTE: authenticated ONLY
--         the person's verdict: the 8-key wire WITHOUT times (the Edge stamps them). The subject is the request's JWT (per-claim settings, else
--         request.jwt.claims; equal to auth.uid(); not anonymous); there is no identity parameter. App / feature / brand id are refused before
--         any row is read. Every fact is read in ONE statement (one snapshot). An unknown brand and a brand the caller is not a member of give
--         the same answer; no other person's id or role, no owner id, no raw session id is ever returned. No exception is caught into a value.
--   W1  private.account_lifecycle_worker_brand_verdict(p_brand_id, p_service_key, p_expected_owner_epoch, p_expected_lifecycle_version) -> text
--         owner-only. A worker's answer for a reservation / attestation bound earlier: F5 P5's brand state, the F5 owner epoch EQUAL to the bound one,
--         and the owner's lifecycle_version EQUAL to the bound one ('active' or a fixed code). lifecycle_version is the service GENERATION: F5 P1's
--         row trigger moves it on every insert / update / delete of the owner's entitlements and on every account status change, and it never goes
--         back -- so a service ended and re-started after the bind (even inside one transaction, or a long one: no clock is compared) is a new
--         generation (H1 C1 P2 of PR #351). The bound pair is what R1's allow token `g5oe:<epoch>:<lifecycle_version>` carries. For a reviewed SQL
--         writer of another owner, inside its statement.
--   W2  public.common_account_worker_brand_verdict(...same...) -> text                                            EXECUTE: service_role ONLY
--         W1 for an Edge worker's last check right before the provider. Never callable by a person.
--   GC  private.account_lifecycle_generation_covered() -> boolean                                                 owner-only
--         whether the service generation (the owner's lifecycle_version) is moved by EXACTLY F5 P1's two triggers (G5-05, H1 C1 P2 on PR #358);
--         checked before and after the install and by W1 on every call (W1 answers SERVICE_GENERATION_UNAVAILABLE otherwise).
--
-- All four are STABLE, SECURITY DEFINER, empty search_path, row_security = off (G5-08: a relation that RLS filters for the owner is an error,
-- never fewer rows), owned by the lifecycle owner, read-only: no write, no row lock, no table, no grant beyond the two above. The install refuses
-- unless the F5 chain (P1..P10) and the owner-epoch candidate (PR #303) are installed, every helper is STABLE / definer / owner-owned, every
-- relation read is a table whose EVERY row this owner sees (RLS off, BYPASSRLS, or the table owner's privileges with RLS not FORCED), PR #303's
-- exposure check is clean (no API role reaches the owner, a
-- superuser, TRIGGER, session_replication_role, ...) and GC is true. Its postconditions check the ACL over the role graph (direct and indirect
-- membership) and GC again.

set local lock_timeout = '5s';

do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_fn text;
  v_rel text;
  v_kind "char";
  v_rls boolean;
  v_forced boolean;
  v_relowner oid;
begin
  if (select r.rolsuper from pg_catalog.pg_roles r where r.oid = v_owner) is distinct from false then
    raise exception 'AUTH_VERDICT_PRECONDITION_OWNER_IS_SUPERUSER';
  end if;
  if to_regprocedure('public.common_account_authorization_verdict(text,text,text)') is not null
     or to_regprocedure('private.account_lifecycle_worker_brand_verdict(text,text,bigint,bigint)') is not null
     or to_regprocedure('public.common_account_worker_brand_verdict(text,text,bigint,bigint)') is not null
     or to_regprocedure('private.account_lifecycle_generation_covered()') is not null then
    raise exception 'AUTH_VERDICT_ALREADY_APPLIED';
  end if;
  -- the helpers this file calls: present, STABLE, definer with an empty search path, owned by this owner
  foreach v_fn in array array['private.account_lifecycle_brand_owner(text)', 'private.account_lifecycle_brand_owner_epoch(text)',
                              'private.account_lifecycle_owner_epoch_exposure()', 'public.common_account_brand_service_state(text,text)', 'auth.uid()'] loop
    if to_regprocedure(v_fn) is null then
      raise exception 'AUTH_VERDICT_PRECONDITION_MISSING %', v_fn;
    end if;
    if v_fn <> 'auth.uid()' and not exists (select 1 from pg_catalog.pg_proc p where p.oid = to_regprocedure(v_fn)
                    and p.provolatile = 's' and p.prosecdef and p.proconfig @> array['search_path=""'] and p.proowner = v_owner) then
      raise exception 'AUTH_VERDICT_PRECONDITION_HELPER_SHAPE %', v_fn;
    end if;
  end loop;
  if (select p.provolatile from pg_catalog.pg_proc p where p.oid = 'auth.uid()'::regprocedure) <> 's' then
    raise exception 'AUTH_VERDICT_PRECONDITION_HELPER_SHAPE auth.uid()';
  end if;
  -- the relations read: plain tables this owner may SELECT, with EVERY row visible to it (G5-08; the class of H1 C1 P2 on PR #383). SELECT alone
  -- is not enough: ordinary RLS still filters a definer owner that neither has the table owner's privileges nor BYPASSRLS, and a hidden row
  -- (an open deletion, another owner) must never read as absent. So RLS off, or BYPASSRLS, or the table owner's privileges with RLS not FORCED
  -- (PostgreSQL's own rule); a view is refused. Every function below also runs with row_security = off: a relation filtered later is an error.
  foreach v_rel in array array['public.common_accounts', 'public.service_entitlements', 'public.brands', 'public.brand_memberships',
                               'private.account_lifecycle_operations', 'auth.users', 'auth.sessions'] loop
    select c.relkind, c.relrowsecurity, c.relforcerowsecurity, c.relowner into v_kind, v_rls, v_forced, v_relowner
      from pg_catalog.pg_class c where c.oid = to_regclass(v_rel);
    if not found or v_kind not in ('r', 'p') or not pg_catalog.has_table_privilege(v_owner, v_rel, 'SELECT') then
      raise exception 'AUTH_VERDICT_PRECONDITION_RELATION %', v_rel;
    end if;
    if v_forced then
      raise exception 'AUTH_VERDICT_PRECONDITION_RLS_FORCED %', v_rel;
    end if;
    if v_rls and not (select r.rolbypassrls from pg_catalog.pg_roles r where r.oid = v_owner) and not pg_catalog.pg_has_role(v_owner, v_relowner, 'USAGE') then
      raise exception 'AUTH_VERDICT_PRECONDITION_RLS_HIDES_ROWS %', v_rel;
    end if;
  end loop;
  if (select count(*) from pg_catalog.pg_attribute a where a.attrelid = 'auth.sessions'::regclass and not a.attisdropped
       and ((a.attname = 'id' and a.atttypid = 'uuid'::regtype) or (a.attname = 'user_id' and a.atttypid = 'uuid'::regtype)
         or (a.attname = 'not_after' and a.atttypid = 'timestamptz'::regtype))) <> 3 then
    raise exception 'AUTH_VERDICT_PRECONDITION_SESSIONS_SHAPE';
  end if;
  -- PR #303's exposure check: no API role reaches the owner, a superuser, TRIGGER, session_replication_role or a membership write
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'AUTH_VERDICT_PRECONDITION_%', private.account_lifecycle_owner_epoch_exposure();
  end if;
end $$;

-- The service generation W1 compares is the owner's lifecycle_version, moved only by F5 P1's two triggers. They count only when they are EXACTLY
-- the P1 triggers (H1 C1 P2 on PR #358): the entitlement trigger AFTER INSERT OR UPDATE OR DELETE FOR EACH ROW (tgtype 29), the account trigger
-- BEFORE UPDATE FOR EACH ROW (tgtype 19), each enabled, not internal, no WHEN clause, no column list, not a constraint / deferrable trigger, no
-- arguments, no transition tables, bound to its P1 function (owned by the table owner, definer, empty search path); no OTHER BEFORE ROW UPDATE
-- trigger on public.common_accounts (one firing after it could put lifecycle_version back), no rule on either table (a DO INSTEAD rule would swallow
-- the bump), and this session honours triggers. Used by the install (pre and post) and by W1 on every call.
create function private.account_lifecycle_generation_covered()
returns boolean language sql stable security definer set search_path = '' set row_security = off as $$
  select pg_catalog.current_setting('session_replication_role') = 'origin'
     and (select pg_catalog.count(*) from pg_catalog.pg_trigger t join pg_catalog.pg_proc f on f.oid = t.tgfoid
           where not t.tgisinternal and t.tgenabled in ('O', 'A')
             and t.tgqual is null and pg_catalog.cardinality(t.tgattr::int2[]) = 0 and t.tgconstraint = 0 and not t.tgdeferrable and not t.tginitdeferred
             and t.tgnargs = 0 and t.tgoldtable is null and t.tgnewtable is null
             and f.proowner = (select c.relowner from pg_catalog.pg_class c where c.oid = t.tgrelid)
             and f.prosecdef and f.proconfig @> array['search_path=""']
             and ((t.tgrelid = 'public.service_entitlements'::regclass and t.tgname = 'account_lifecycle_touch_entitlement' and t.tgtype = 29
                   and t.tgfoid = 'private.account_lifecycle_touch_entitlement()'::regprocedure)
               or (t.tgrelid = 'public.common_accounts'::regclass and t.tgname = 'account_lifecycle_touch_account' and t.tgtype = 19
                   and t.tgfoid = 'private.account_lifecycle_touch_account()'::regprocedure))) = 2
     and not exists (select 1 from pg_catalog.pg_trigger t
                      where t.tgrelid = 'public.common_accounts'::regclass and not t.tgisinternal and t.tgenabled <> 'D'
                        and t.tgtype & 1 = 1 and t.tgtype & 2 = 2 and t.tgtype & 16 = 16
                        and t.tgname <> 'account_lifecycle_touch_account')
     and not exists (select 1 from pg_catalog.pg_rewrite r where r.ev_class in ('public.common_accounts'::regclass, 'public.service_entitlements'::regclass))
$$;
revoke all on function private.account_lifecycle_generation_covered() from public, anon, authenticated, service_role;

do $$
begin
  if not private.account_lifecycle_generation_covered() then
    raise exception 'AUTH_VERDICT_PRECONDITION_LIFECYCLE_TRIGGERS';
  end if;
end $$;

-- R1: the person's verdict.
create function public.common_account_authorization_verdict(p_app text, p_feature text, p_brand_id text)
returns jsonb language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_scope jsonb := pg_catalog.jsonb_build_object('app', p_app, 'feature', p_feature, 'brand_slug', p_brand_id);
  v_claims jsonb;
  v_sub text;
  v_role text;
  v_session text;
  v_anonymous text;
  v_user uuid;
  v_session_id uuid;
  v_subject jsonb;
  v_session_ref text;
  -- the facts, one statement
  f_user_exists boolean;
  f_session_state text;
  f_account_status text;
  f_lifecycle bigint;
  f_account_deletion boolean;
  f_ent_status text;
  f_ent_deletion boolean;
  f_brand_found boolean;
  f_brand_kind text;
  f_caller_role text;
  f_owner uuid;
  f_owner_count bigint;
  f_epoch bigint;
begin
  -- 1. the subject: the request's JWT only (F5 P3b's sources: the per-claim settings of an older PostgREST, else the JSON claims) (I-1). No row is
  --    read here: settings and auth.uid() only.
  v_sub := nullif(pg_catalog.current_setting('request.jwt.claim.sub', true), '');
  if v_sub is not null then
    v_role := nullif(pg_catalog.current_setting('request.jwt.claim.role', true), '');
    v_session := nullif(pg_catalog.current_setting('request.jwt.claim.session_id', true), '');
    v_anonymous := coalesce(nullif(pg_catalog.current_setting('request.jwt.claim.is_anonymous', true), ''), 'false');
  else
    begin
      v_claims := nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb;
    exception when others then
      v_claims := null;
    end;
    if pg_catalog.jsonb_typeof(v_claims) = 'object' then
      v_sub := v_claims ->> 'sub';
      v_role := v_claims ->> 'role';
      v_session := v_claims ->> 'session_id';
      -- absent or JSON null = not anonymous; anything but the JSON boolean false is anonymous
      v_anonymous := coalesce(nullif((v_claims -> 'is_anonymous')::text, 'null'), 'false');
    end if;
  end if;
  if v_sub ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and v_session ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and v_role = 'authenticated' and v_anonymous = 'false' then
    if (select auth.uid()) is not distinct from v_sub::uuid then
      v_user := v_sub::uuid;
      v_session_id := v_session::uuid;
      v_subject := pg_catalog.jsonb_build_object('kind', 'user', 'user_id', v_user);
    end if;
  end if;

  -- 2. the question, before any row is read (I-2): app, feature, brand id. The refusal names the caller only when the caller was accepted above.
  if p_app is distinct from 'postona'
     or p_feature is null or p_feature not in ('read_workspace', 'x_connect', 'x_publish', 'threads_connect', 'threads_publish', 'consult', 'post_generation') then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'FEATURE_NOT_ENABLED', 'scope', v_scope,
      'subject', coalesce(v_subject, pg_catalog.jsonb_build_object('kind', 'system')), 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;
  if p_brand_id is null or p_brand_id !~ '^[a-z][a-z0-9_-]{0,63}$' then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'BRAND_REQUIRED', 'scope', v_scope,
      'subject', coalesce(v_subject, pg_catalog.jsonb_build_object('kind', 'system')), 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;
  if v_user is null then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'AUTH_REQUIRED', 'scope', v_scope,
      'subject', pg_catalog.jsonb_build_object('kind', 'system'), 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;

  -- 3. every fact in ONE statement: the caller's login, session, account, x_autopost entitlement, the brand, the caller's role, the single owner and
  --    the owner epoch (I-4, I-5). Read as the lifecycle owner; nothing of another person is returned.
  select exists (select 1 from auth.users u where u.id = v_user),
         (select case when s.id is null then 'revoked'
                      when s.not_after is null or s.not_after > pg_catalog.clock_timestamp() then 'active' else 'expired' end
            from (select 1) x left join auth.sessions s on s.id = v_session_id and s.user_id = v_user),
         a.status, a.lifecycle_version,
         (a.status = 'deleting' or exists (select 1 from private.account_lifecycle_operations o
                                            where o.user_id = v_user and o.operation_type = 'account_deletion' and o.status = 'in_progress')),
         e.status,
         exists (select 1 from private.account_lifecycle_operations o
                  where o.user_id = v_user and o.operation_type = 'service_deletion' and o.service_key = 'x_autopost' and o.status = 'in_progress'),
         b.id is not null, b.code_profile_key,
         (select m.role from public.brand_memberships m where m.brand_id = b.id and m.user_id = v_user),
         private.account_lifecycle_brand_owner(b.id),
         (select pg_catalog.count(*) from public.brand_memberships o where o.brand_id = b.id and o.role = 'owner'),
         private.account_lifecycle_brand_owner_epoch(b.id)
    into f_user_exists, f_session_state, f_account_status, f_lifecycle, f_account_deletion, f_ent_status, f_ent_deletion,
         f_brand_found, f_brand_kind, f_caller_role, f_owner, f_owner_count, f_epoch
    from (select 1) x
    left join public.common_accounts a on a.user_id = v_user
    left join public.service_entitlements e on e.user_id = v_user and e.service_key = 'x_autopost'
    left join public.brands b on b.id = p_brand_id;

  if not f_user_exists then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'AUTH_REQUIRED', 'scope', v_scope,
      'subject', v_subject, 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;
  -- the session reference is a hash: the raw session id never leaves this function
  v_session_ref := 's:' || pg_catalog.left(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('g5-session:' || v_session_id::text, 'UTF8')), 'hex'), 32);
  if f_session_state <> 'active' then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', case f_session_state when 'revoked' then 'SESSION_REVOKED' else 'SESSION_EXPIRED' end,
      'scope', v_scope, 'subject', v_subject, 'session', pg_catalog.jsonb_build_object('state', f_session_state, 'ref', v_session_ref),
      'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;

  -- 4. the decision, in the order of the reference (decide() in verdict.ts); anything unexpected is unknown, never allow (I-8)
  return case
    when f_account_status is null then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'ACCOUNT_NOT_FOUND')
    when f_lifecycle is null or f_lifecycle < 1 then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'unknown', 'reason', 'ACCOUNT_UNREADABLE')
    when f_account_deletion then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'ACCOUNT_DELETION_IN_PROGRESS')
    when f_account_status = 'locked' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'ACCOUNT_LOCKED')
    when f_account_status <> 'active' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'unknown', 'reason', 'ACCOUNT_STATE_UNKNOWN')
    when f_ent_status is null then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'SERVICE_NOT_REGISTERED')
    when f_ent_status = 'deleting' or f_ent_deletion then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'SERVICE_DELETION_IN_PROGRESS')
    when f_ent_status = 'provisioning' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'pending', 'reason', 'SERVICE_PROVISIONING')
    when f_ent_status = 'suspended' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'SERVICE_SUSPENDED')
    when f_ent_status = 'ended' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'SERVICE_NOT_ACTIVE')
    when f_ent_status <> 'active' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'unknown', 'reason', 'SERVICE_STATE_UNKNOWN')
    -- an unknown brand and a brand the caller is not a member of: the same answer (I-3)
    when not f_brand_found or f_caller_role is null then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'BRAND_ACCESS_DENIED')
    when f_caller_role <> 'owner' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'ROLE_NOT_ALLOWED')
    when f_brand_kind is distinct from 'social_mobile_user_v1' then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'WORKSPACE_KIND_UNSUPPORTED')
    when f_owner_count <> 1 or f_owner is null then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'unknown', 'reason', 'WORKSPACE_OWNER_UNKNOWN')
    when f_owner <> v_user then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'BRAND_ACCESS_DENIED')
    when f_epoch is null or f_epoch < 1 then
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'unknown', 'reason', 'OWNER_EPOCH_UNAVAILABLE')
    else
      pg_catalog.jsonb_build_object('v', 1, 'decision', 'allow', 'reason', null)
  end || pg_catalog.jsonb_build_object('scope', v_scope, 'subject', v_subject)
      || case
           when f_account_status = 'active' and not f_account_deletion and f_ent_status = 'active' and not f_ent_deletion and f_brand_found
                and f_caller_role = 'owner' and f_brand_kind = 'social_mobile_user_v1' and f_owner_count = 1 and f_owner = v_user and f_epoch >= 1
                and f_lifecycle >= 1 then
             pg_catalog.jsonb_build_object('session', pg_catalog.jsonb_build_object('state', 'active', 'ref', v_session_ref),
               'owner_epoch', 'g5oe:' || f_epoch::text || ':' || f_lifecycle::text, 'entitlements', '["postona:x_autopost"]'::jsonb)
           else
             pg_catalog.jsonb_build_object('session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb)
         end;
end $$;

-- W1: the worker's answer for a reservation / attestation bound earlier. The bind is the pair (owner epoch, owner lifecycle_version) -- both
-- monotonic counters, compared for EQUALITY in one statement; no timestamp is trusted.
create function private.account_lifecycle_worker_brand_verdict(p_brand_id text, p_service_key text, p_expected_owner_epoch bigint, p_expected_lifecycle_version bigint)
returns text language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_state text;
  v_epoch bigint;
  v_lifecycle bigint;
  v_covered boolean;
begin
  if p_service_key is distinct from 'x_autopost' then
    return 'ACCOUNT_LIFECYCLE_SERVICE_INVALID';
  end if;
  if p_expected_owner_epoch is null or p_expected_owner_epoch < 1 then
    return 'EXPECTED_OWNER_EPOCH_REQUIRED';
  end if;
  if p_expected_lifecycle_version is null or p_expected_lifecycle_version < 1 then
    return 'EXPECTED_LIFECYCLE_VERSION_REQUIRED';
  end if;
  -- one statement: F5 P5's state, the owner epoch, the owner's lifecycle_version (the service generation) and whether that counter is covered
  select public.common_account_brand_service_state(p_brand_id, p_service_key),
         private.account_lifecycle_brand_owner_epoch(p_brand_id),
         (select a.lifecycle_version from public.common_accounts a where a.user_id = private.account_lifecycle_brand_owner(p_brand_id)),
         private.account_lifecycle_generation_covered()
    into v_state, v_epoch, v_lifecycle, v_covered;
  if v_state is distinct from 'active' then
    return case when v_state in ('WORKSPACE_OWNER_UNKNOWN', 'ACCOUNT_LIFECYCLE_ACCOUNT_NOT_FOUND', 'ACCOUNT_DELETION_IN_PROGRESS', 'ACCOUNT_LOCKED',
                                 'SERVICE_NOT_REGISTERED', 'SERVICE_DELETION_IN_PROGRESS', 'SERVICE_NOT_ACTIVE', 'ACCOUNT_LIFECYCLE_SERVICE_INVALID')
                then v_state else 'SERVICE_STATE_UNKNOWN' end;
  end if;
  if v_epoch is null or v_epoch < 1 then
    return 'OWNER_EPOCH_UNAVAILABLE';
  end if;
  -- the generation is only a fence while its triggers are exactly P1's (checked on every call, not only at install)
  if v_covered is not true then
    return 'SERVICE_GENERATION_UNAVAILABLE';
  end if;
  if v_epoch <> p_expected_owner_epoch then
    return 'OWNER_EPOCH_CHANGED';
  end if;
  -- null-safe: an unreadable generation is a changed one (P5 'active' implies the account row, so NULL is not expected here)
  if v_lifecycle is distinct from p_expected_lifecycle_version then
    return 'SERVICE_GENERATION_CHANGED';
  end if;
  return 'active';
end $$;

-- W2: W1 for an Edge worker (service_role).
create function public.common_account_worker_brand_verdict(p_brand_id text, p_service_key text, p_expected_owner_epoch bigint, p_expected_lifecycle_version bigint)
returns text language sql stable security definer set search_path = '' set row_security = off as $$
  select private.account_lifecycle_worker_brand_verdict(p_brand_id, p_service_key, p_expected_owner_epoch, p_expected_lifecycle_version)
$$;

revoke all on function public.common_account_authorization_verdict(text, text, text),
  private.account_lifecycle_worker_brand_verdict(text, text, bigint, bigint),
  public.common_account_worker_brand_verdict(text, text, bigint, bigint), private.account_lifecycle_generation_covered()
  from public, anon, authenticated, service_role;
grant execute on function public.common_account_authorization_verdict(text, text, text) to authenticated;
grant execute on function public.common_account_worker_brand_verdict(text, text, bigint, bigint) to service_role;

-- Postconditions: the exact ACL, the shape, and the role graph -- every role an API role is a MEMBER of (direct or indirect, INHERIT or not,
-- SET or not, ADMIN-only) is checked with its own privileges. authenticator reaching authenticated / service_role is PostgREST's role switch.
do $$
declare
  v_owner text := quote_ident(current_user);
  v_r1 regprocedure := 'public.common_account_authorization_verdict(text,text,text)'::regprocedure;
  v_w1 regprocedure := 'private.account_lifecycle_worker_brand_verdict(text,text,bigint,bigint)'::regprocedure;
  v_w2 regprocedure := 'public.common_account_worker_brand_verdict(text,text,bigint,bigint)'::regprocedure;
  v_gc regprocedure := 'private.account_lifecycle_generation_covered()'::regprocedure;
  v_fn regprocedure;
  v_allowed text;
begin
  if (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_r1) is distinct from format('%s=X/%s,authenticated=X/%s', v_owner, v_owner, v_owner)
     or (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_w2) is distinct from format('%s=X/%s,service_role=X/%s', v_owner, v_owner, v_owner)
     or (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_w1) is distinct from format('%s=X/%s', v_owner, v_owner)
     or (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_gc) is distinct from format('%s=X/%s', v_owner, v_owner) then
    raise exception 'AUTH_VERDICT_POSTCONDITION_ACL';
  end if;
  foreach v_fn in array array[v_r1, v_w1, v_w2, v_gc] loop
    if not exists (select 1 from pg_catalog.pg_proc p where p.oid = v_fn and p.provolatile = 's' and p.prosecdef
                    and p.proconfig @> array['search_path=""', 'row_security=off']
                    and p.proowner = (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user)) then
      raise exception 'AUTH_VERDICT_POSTCONDITION_SHAPE %', v_fn;
    end if;
    v_allowed := case v_fn when v_r1 then 'authenticated' when v_w2 then 'service_role' else null end;
    if exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
                where a.rolname in ('anon', 'authenticated', 'service_role')
                  and a.rolname is distinct from v_allowed
                  and pg_catalog.has_function_privilege(r.oid, v_fn, 'EXECUTE')) then
      raise exception 'AUTH_VERDICT_POSTCONDITION_API_ROLE_REACHES %', v_fn;
    end if;
    if exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
                where a.rolname = 'authenticator' and r.rolname not in ('authenticator', 'anon', 'authenticated', 'service_role')
                  and pg_catalog.has_function_privilege(r.oid, v_fn, 'EXECUTE')) then
      raise exception 'AUTH_VERDICT_POSTCONDITION_API_ROLE_REACHES %', v_fn;
    end if;
  end loop;
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'AUTH_VERDICT_POSTCONDITION_EXPOSURE';
  end if;
  if not private.account_lifecycle_generation_covered() then
    raise exception 'AUTH_VERDICT_POSTCONDITION_LIFECYCLE_TRIGGERS';
  end if;
end $$;


-- ==== part 20_r0_bootstrap_verdict.sql (blob f78d87a9e66d054775076fc0edf1867f077b0e70): its own begin; / commit; removed, nothing else changed ====
-- G5 SOURCE CANDIDATE (2026-10-20, Issue #320 G5-01 task 7). NOT in supabase/migrations/. Never apply to a managed or production database without
-- an independent focused Codex Sol (high) review of this file, the G5 担当ちゃ's acceptance and the owner's explicit production approval.
--
-- R0  public.common_account_bootstrap_verdict(p_app text, p_feature text) -> jsonb                                  EXECUTE: authenticated ONLY
--       The brand-less BOOTSTRAP verdict for the FIRST POSTONA X / Threads connection (contract: docs/common-account/g5-06-brandless-oauth-bootstrap.md
--       §4; reference: bootstrapVerdict() in supabase/candidates/common_account_postona_authz/bootstrap.ts, which the PG17 suite uses as the oracle).
--       It answers only "may this person START a connection now": R1's person checks (the subject from the JWT claims only -- the per-claim settings
--       of an older PostgREST, else request.jwt.claims; equal to auth.uid(); not anonymous; a live auth.sessions row), the common account and the
--       x_autopost entitlement; plus ONE fact about the person's own workspace, looked up by the id the SERVER derives from the subject with the rule
--       the begin RPC and the deletion saga use ('u_' || substr(md5(user), 1, 24)): absent, or exactly theirs (a user workspace whose single owner
--       is the caller). There is no brand and no person parameter. The answer is the G5-01 8-key wire without times, with scope.brand_slug null and
--       owner_epoch null; the Edge stamps the times (allow 60 s). An allow authorises ONLY the begin of that connection: R1 does not answer the
--       bootstrap features, a worker cannot bind to it (no owner epoch), and the code exchange stays behind R1 + a recheck.
--
-- STABLE, SECURITY DEFINER, empty search_path, owned by the lifecycle owner, read-only: no write, no row lock, no workspace, no OAuth state, no
-- grant beyond the one above. Installed after 001_authorization_verdict.sql (it does not depend on it; the two never call each other). The install
-- refuses unless the F5 chain and the owner-epoch candidate are installed (helpers STABLE / definer / owner-owned), every relation read is a
-- table whose EVERY row this owner sees (RLS off, BYPASSRLS, or the table owner's privileges with RLS not FORCED -- G5-08, H1 C1 P2 on PR #383)
-- and PR #303's exposure check is clean; R0 runs with row_security = off (a relation filtered later is an error, never fewer rows); its
-- postconditions check the exact ACL and the role graph (direct and indirect membership).

set local lock_timeout = '5s';

do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_fn text;
  v_rel text;
  v_kind "char";
  v_rls boolean;
  v_forced boolean;
  v_relowner oid;
begin
  if (select r.rolsuper from pg_catalog.pg_roles r where r.oid = v_owner) is distinct from false then
    raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_OWNER_IS_SUPERUSER';
  end if;
  if to_regprocedure('public.common_account_bootstrap_verdict(text,text)') is not null then
    raise exception 'BOOTSTRAP_VERDICT_ALREADY_APPLIED';
  end if;
  -- the helper this file calls (the exposure check) and auth.uid(): present; the helper STABLE, definer, empty search path, owned by this owner
  foreach v_fn in array array['private.account_lifecycle_owner_epoch_exposure()', 'auth.uid()'] loop
    if to_regprocedure(v_fn) is null then
      raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_MISSING %', v_fn;
    end if;
  end loop;
  if not exists (select 1 from pg_catalog.pg_proc p where p.oid = 'private.account_lifecycle_owner_epoch_exposure()'::regprocedure
                  and p.provolatile = 's' and p.prosecdef and p.proconfig @> array['search_path=""'] and p.proowner = v_owner)
     or (select p.provolatile from pg_catalog.pg_proc p where p.oid = 'auth.uid()'::regprocedure) <> 's' then
    raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_HELPER_SHAPE';
  end if;
  -- the relations read: plain tables this owner may SELECT, with EVERY row visible to it (H1 C1 P2 on PR #383). SELECT alone is not enough: a
  -- SECURITY DEFINER function runs as its owner, and ordinary RLS still filters an owner that neither has the table owner's privileges nor
  -- BYPASSRLS -- a hidden row (another person's workspace under the derived id, an open deletion) would look absent and an absent workspace is
  -- an allow. So RLS must be off, or this owner must have BYPASSRLS, or this owner must have the table owner's privileges with RLS not FORCED
  -- (PostgreSQL's own rule). A view is refused (its WHERE could hide rows). R0 also runs with row_security = off, so a relation that becomes
  -- filtered after this install raises an error instead of returning fewer rows.
  foreach v_rel in array array['public.common_accounts', 'public.service_entitlements', 'public.brands', 'public.brand_memberships',
                               'private.account_lifecycle_operations', 'auth.users', 'auth.sessions'] loop
    select c.relkind, c.relrowsecurity, c.relforcerowsecurity, c.relowner into v_kind, v_rls, v_forced, v_relowner
      from pg_catalog.pg_class c where c.oid = to_regclass(v_rel);
    if not found or v_kind not in ('r', 'p') or not pg_catalog.has_table_privilege(v_owner, v_rel, 'SELECT') then
      raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_RELATION %', v_rel;
    end if;
    if v_forced then
      raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_RLS_FORCED %', v_rel;
    end if;
    if v_rls and not (select r.rolbypassrls from pg_catalog.pg_roles r where r.oid = v_owner) and not pg_catalog.pg_has_role(v_owner, v_relowner, 'USAGE') then
      raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_RLS_HIDES_ROWS %', v_rel;
    end if;
  end loop;
  if (select count(*) from pg_catalog.pg_attribute a where a.attrelid = 'auth.sessions'::regclass and not a.attisdropped
       and ((a.attname = 'id' and a.atttypid = 'uuid'::regtype) or (a.attname = 'user_id' and a.atttypid = 'uuid'::regtype)
         or (a.attname = 'not_after' and a.atttypid = 'timestamptz'::regtype))) <> 3 then
    raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_SESSIONS_SHAPE';
  end if;
  -- the derivation must be the one the deletion saga names (main 20260928160000:98-100), so R0 and the begin / deletion paths agree on the id
  if to_regprocedure('public.social_mobile_account_deletion_workspace(uuid)') is null
     or public.social_mobile_account_deletion_workspace('00000000-0000-4000-8000-000000000001'::uuid)
        is distinct from 'u_' || pg_catalog.substr(pg_catalog.md5('00000000-0000-4000-8000-000000000001'), 1, 24) then
    raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_WORKSPACE_DERIVATION';
  end if;
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'BOOTSTRAP_VERDICT_PRECONDITION_%', private.account_lifecycle_owner_epoch_exposure();
  end if;
end $$;

-- R0: the brand-less bootstrap verdict.
create function public.common_account_bootstrap_verdict(p_app text, p_feature text)
returns jsonb language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_scope jsonb := pg_catalog.jsonb_build_object('app', p_app, 'feature', p_feature, 'brand_slug', null);
  v_claims jsonb;
  v_sub text;
  v_role text;
  v_session text;
  v_anonymous text;
  v_user uuid;
  v_session_id uuid;
  v_subject jsonb;
  v_session_ref text;
  v_workspace text;
  -- the facts, one statement
  f_user_exists boolean;
  f_session_state text;
  f_account_status text;
  f_lifecycle bigint;
  f_account_deletion boolean;
  f_ent_status text;
  f_ent_deletion boolean;
  f_ws_found boolean;
  f_ws_kind text;
  f_caller_role text;
  f_owner uuid;
  f_owner_count bigint;
  v_person jsonb;
begin
  -- 1. the question, before anything else: only the two bootstrap features of POSTONA (no brand parameter exists)
  if p_app is distinct from 'postona' or p_feature is null or p_feature not in ('x_connect_bootstrap', 'threads_connect_bootstrap') then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'FEATURE_NOT_ENABLED', 'scope', v_scope,
      'subject', pg_catalog.jsonb_build_object('kind', 'system'), 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;

  -- 2. the subject: the request's JWT only, exactly as R1 (settings and auth.uid() only; no row is read)
  v_sub := nullif(pg_catalog.current_setting('request.jwt.claim.sub', true), '');
  if v_sub is not null then
    v_role := nullif(pg_catalog.current_setting('request.jwt.claim.role', true), '');
    v_session := nullif(pg_catalog.current_setting('request.jwt.claim.session_id', true), '');
    v_anonymous := coalesce(nullif(pg_catalog.current_setting('request.jwt.claim.is_anonymous', true), ''), 'false');
  else
    begin
      v_claims := nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb;
    exception when others then
      v_claims := null;
    end;
    if pg_catalog.jsonb_typeof(v_claims) = 'object' then
      v_sub := v_claims ->> 'sub';
      v_role := v_claims ->> 'role';
      v_session := v_claims ->> 'session_id';
      v_anonymous := coalesce(nullif((v_claims -> 'is_anonymous')::text, 'null'), 'false');
    end if;
  end if;
  if v_sub ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and v_session ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and v_role = 'authenticated' and v_anonymous = 'false' then
    if (select auth.uid()) is not distinct from v_sub::uuid then
      v_user := v_sub::uuid;
      v_session_id := v_session::uuid;
      v_subject := pg_catalog.jsonb_build_object('kind', 'user', 'user_id', v_user);
    end if;
  end if;
  if v_user is null then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'AUTH_REQUIRED', 'scope', v_scope,
      'subject', pg_catalog.jsonb_build_object('kind', 'system'), 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;

  -- 3. the person's own workspace id, derived on the server from the verified subject (never from the request)
  v_workspace := 'u_' || pg_catalog.substr(pg_catalog.md5(v_user::text), 1, 24);

  -- 4. every fact in ONE statement: the caller's login, session, account, x_autopost entitlement and the own workspace (kind, the caller's role,
  --    the owner count, the single owner). Read as the lifecycle owner; nothing of another person is returned.
  select exists (select 1 from auth.users u where u.id = v_user),
         (select case when s.id is null then 'revoked'
                      when s.not_after is null or s.not_after > pg_catalog.clock_timestamp() then 'active' else 'expired' end
            from (select 1) x left join auth.sessions s on s.id = v_session_id and s.user_id = v_user),
         a.status, a.lifecycle_version,
         (a.status = 'deleting' or exists (select 1 from private.account_lifecycle_operations o
                                            where o.user_id = v_user and o.operation_type = 'account_deletion' and o.status = 'in_progress')),
         e.status,
         exists (select 1 from private.account_lifecycle_operations o
                  where o.user_id = v_user and o.operation_type = 'service_deletion' and o.service_key = 'x_autopost' and o.status = 'in_progress'),
         b.id is not null, b.code_profile_key,
         (select m.role from public.brand_memberships m where m.brand_id = b.id and m.user_id = v_user),
         (select case when pg_catalog.count(*) = 1 then (pg_catalog.array_agg(m.user_id))[1] end
            from public.brand_memberships m where m.brand_id = b.id and m.role = 'owner'),
         (select pg_catalog.count(*) from public.brand_memberships o where o.brand_id = b.id and o.role = 'owner')
    into f_user_exists, f_session_state, f_account_status, f_lifecycle, f_account_deletion, f_ent_status, f_ent_deletion,
         f_ws_found, f_ws_kind, f_caller_role, f_owner, f_owner_count
    from (select 1) x
    left join public.common_accounts a on a.user_id = v_user
    left join public.service_entitlements e on e.user_id = v_user and e.service_key = 'x_autopost'
    left join public.brands b on b.id = v_workspace;

  if not f_user_exists then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', 'AUTH_REQUIRED', 'scope', v_scope,
      'subject', v_subject, 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;
  v_session_ref := 's:' || pg_catalog.left(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to('g5-session:' || v_session_id::text, 'UTF8')), 'hex'), 32);
  if f_session_state <> 'active' then
    return pg_catalog.jsonb_build_object('v', 1, 'decision', 'deny', 'reason', case f_session_state when 'revoked' then 'SESSION_REVOKED' else 'SESSION_EXPIRED' end,
      'scope', v_scope, 'subject', v_subject, 'session', pg_catalog.jsonb_build_object('state', f_session_state, 'ref', v_session_ref),
      'owner_epoch', null, 'entitlements', '[]'::jsonb);
  end if;

  -- 5. the person checks (R1's order), then the own-workspace rule; anything unexpected is unknown, never allow
  v_person := case
    when f_account_status is null then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'ACCOUNT_NOT_FOUND')
    when f_lifecycle is null or f_lifecycle < 1 then pg_catalog.jsonb_build_object('decision', 'unknown', 'reason', 'ACCOUNT_UNREADABLE')
    when f_account_deletion then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'ACCOUNT_DELETION_IN_PROGRESS')
    when f_account_status = 'locked' then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'ACCOUNT_LOCKED')
    when f_account_status <> 'active' then pg_catalog.jsonb_build_object('decision', 'unknown', 'reason', 'ACCOUNT_STATE_UNKNOWN')
    when f_ent_status is null then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'SERVICE_NOT_REGISTERED')
    when f_ent_status = 'deleting' or f_ent_deletion then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'SERVICE_DELETION_IN_PROGRESS')
    when f_ent_status = 'provisioning' then pg_catalog.jsonb_build_object('decision', 'pending', 'reason', 'SERVICE_PROVISIONING')
    when f_ent_status = 'suspended' then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'SERVICE_SUSPENDED')
    when f_ent_status = 'ended' then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'SERVICE_NOT_ACTIVE')
    when f_ent_status <> 'active' then pg_catalog.jsonb_build_object('decision', 'unknown', 'reason', 'SERVICE_STATE_UNKNOWN')
    -- the own workspace: absent, or exactly the caller's; a workspace under the derived id that is not is never joined
    when not f_ws_found then null
    when f_ws_kind is distinct from 'social_mobile_user_v1' then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'OWN_WORKSPACE_CONFLICT')
    when f_owner_count <> 1 or f_owner is null then pg_catalog.jsonb_build_object('decision', 'unknown', 'reason', 'WORKSPACE_OWNER_UNKNOWN')
    when f_owner <> v_user or f_caller_role is distinct from 'owner' then pg_catalog.jsonb_build_object('decision', 'deny', 'reason', 'OWN_WORKSPACE_CONFLICT')
    else null
  end;
  if v_person is not null then
    return pg_catalog.jsonb_build_object('v', 1, 'scope', v_scope, 'subject', v_subject, 'session', null, 'owner_epoch', null, 'entitlements', '[]'::jsonb) || v_person;
  end if;
  return pg_catalog.jsonb_build_object('v', 1, 'decision', 'allow', 'reason', null, 'scope', v_scope, 'subject', v_subject,
    'session', pg_catalog.jsonb_build_object('state', 'active', 'ref', v_session_ref), 'owner_epoch', null, 'entitlements', '["postona:x_autopost"]'::jsonb);
end $$;

revoke all on function public.common_account_bootstrap_verdict(text, text) from public, anon, authenticated, service_role;
grant execute on function public.common_account_bootstrap_verdict(text, text) to authenticated;

-- Postconditions: the exact ACL, the shape, the role graph (every role an API role is a MEMBER of; authenticator reaching the API roles is PostgREST's
-- role switch), and the exposure check.
do $$
declare
  v_owner text := quote_ident(current_user);
  v_r0 regprocedure := 'public.common_account_bootstrap_verdict(text,text)'::regprocedure;
begin
  if (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_r0) is distinct from format('%s=X/%s,authenticated=X/%s', v_owner, v_owner, v_owner) then
    raise exception 'BOOTSTRAP_VERDICT_POSTCONDITION_ACL';
  end if;
  if not exists (select 1 from pg_catalog.pg_proc p where p.oid = v_r0 and p.provolatile = 's' and p.prosecdef
                  and p.proconfig @> array['search_path=""', 'row_security=off'] and p.proowner = (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user)) then
    raise exception 'BOOTSTRAP_VERDICT_POSTCONDITION_SHAPE';
  end if;
  if exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
              where a.rolname in ('anon', 'service_role') and pg_catalog.has_function_privilege(r.oid, v_r0, 'EXECUTE'))
     or exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
              where a.rolname = 'authenticator' and r.rolname not in ('authenticator', 'anon', 'authenticated', 'service_role')
                and pg_catalog.has_function_privilege(r.oid, v_r0, 'EXECUTE')) then
    raise exception 'BOOTSTRAP_VERDICT_POSTCONDITION_API_ROLE_REACHES';
  end if;
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'BOOTSTRAP_VERDICT_POSTCONDITION_EXPOSURE';
  end if;
end $$;


-- ==== part 30_sv_session_verdict.sql (blob a0680eb32397b66bb64bdd5e946a02c7ee09eabd): its own begin; / commit; removed, nothing else changed ====
-- G5 SOURCE CANDIDATE (2026-10-21, Issue #320 G5-01 task 10). NOT in supabase/migrations/. Never apply to a managed or production database without
-- an independent focused Codex Sol (high) review of this file, the G5 担当ちゃ's acceptance and the owner's explicit production approval.
--
-- SV  private.account_lifecycle_session_verdict() -> text                                          EXECUTE: the lifecycle owner ONLY (no grant)
--       The SESSION-ONLY verdict (contract: docs/common-account/g5-09-session-verdict-interface.md §4; reference: sessionVerdict() in
--       supabase/candidates/common_account_postona_authz/session_verdict.ts, which the PG17 suite uses as the oracle). It answers only "is this
--       request made by a signed-in, non-anonymous person whose session is live right now": R1's subject stage (the claims only -- the per-claim
--       settings of an older PostgREST, else request.jwt.claims; sub and session_id uuids; role authenticated; not anonymous; sub = auth.uid()),
--       then the login and the auth.sessions row by id AND user_id with not_after in the future. Nothing about the common account, an entitlement
--       or a brand: a person-facing read / stop (G3's reservation receipt / cancel, P7 of G3 PR #392) keeps working after a service ended.
--       -> 'active' | 'AUTH_REQUIRED' | 'SESSION_REVOKED' | 'SESSION_EXPIRED'. An unreadable fact RAISES (never 'active').
--       No parameter: there is no user id, session id or brand to pass.
--
-- STABLE, SECURITY DEFINER, empty search_path, row_security = off, owned by the lifecycle owner, read-only: no write, no row lock, no grant. A
-- consumer is a reviewed function owned by the same owner (or one given a separately reviewed grant later), which calls it FIRST and touches no row
-- unless it answered 'active'. Independent of 001 / 002 (it calls neither). The install refuses unless auth.uid() and PR #303's exposure check are
-- present, both relations read (auth.users, auth.sessions) are tables whose EVERY row this owner sees (G5-08: RLS off, BYPASSRLS, or the table
-- owner's privileges with RLS not FORCED), auth.sessions has the expected shape and the exposure check is clean; its postconditions check the exact
-- ACL and that no API role reaches it over the role graph.

set local lock_timeout = '5s';

do $$
declare
  v_owner oid := (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user);
  v_rel text;
  v_kind "char";
  v_rls boolean;
  v_forced boolean;
  v_relowner oid;
begin
  if (select r.rolsuper from pg_catalog.pg_roles r where r.oid = v_owner) is distinct from false then
    raise exception 'SESSION_VERDICT_PRECONDITION_OWNER_IS_SUPERUSER';
  end if;
  if to_regprocedure('private.account_lifecycle_session_verdict()') is not null then
    raise exception 'SESSION_VERDICT_ALREADY_APPLIED';
  end if;
  if to_regnamespace('private') is null or not pg_catalog.has_schema_privilege(v_owner, 'private', 'CREATE') then
    raise exception 'SESSION_VERDICT_PRECONDITION_SCHEMA';
  end if;
  -- auth.uid() (STABLE) and PR #303's exposure check (STABLE, definer, empty search path, owned by this owner)
  if to_regprocedure('auth.uid()') is null or (select p.provolatile from pg_catalog.pg_proc p where p.oid = 'auth.uid()'::regprocedure) <> 's' then
    raise exception 'SESSION_VERDICT_PRECONDITION_HELPER_SHAPE auth.uid()';
  end if;
  if to_regprocedure('private.account_lifecycle_owner_epoch_exposure()') is null
     or not exists (select 1 from pg_catalog.pg_proc p where p.oid = 'private.account_lifecycle_owner_epoch_exposure()'::regprocedure
                     and p.provolatile = 's' and p.prosecdef and p.proconfig @> array['search_path=""'] and p.proowner = v_owner) then
    raise exception 'SESSION_VERDICT_PRECONDITION_HELPER_SHAPE private.account_lifecycle_owner_epoch_exposure()';
  end if;
  -- the relations read: plain tables this owner may SELECT, with EVERY row visible to it (G5-08). A hidden row can only turn 'active' into a
  -- refusal here (allow needs the session row), but install and call apply the same rule as R0 / R1, and the call runs with row_security = off.
  foreach v_rel in array array['auth.users', 'auth.sessions'] loop
    select c.relkind, c.relrowsecurity, c.relforcerowsecurity, c.relowner into v_kind, v_rls, v_forced, v_relowner
      from pg_catalog.pg_class c where c.oid = to_regclass(v_rel);
    if not found or v_kind not in ('r', 'p') or not pg_catalog.has_table_privilege(v_owner, v_rel, 'SELECT') then
      raise exception 'SESSION_VERDICT_PRECONDITION_RELATION %', v_rel;
    end if;
    if v_forced then
      raise exception 'SESSION_VERDICT_PRECONDITION_RLS_FORCED %', v_rel;
    end if;
    if v_rls and not (select r.rolbypassrls from pg_catalog.pg_roles r where r.oid = v_owner) and not pg_catalog.pg_has_role(v_owner, v_relowner, 'USAGE') then
      raise exception 'SESSION_VERDICT_PRECONDITION_RLS_HIDES_ROWS %', v_rel;
    end if;
  end loop;
  if (select count(*) from pg_catalog.pg_attribute a where a.attrelid = 'auth.sessions'::regclass and not a.attisdropped
       and ((a.attname = 'id' and a.atttypid = 'uuid'::regtype) or (a.attname = 'user_id' and a.atttypid = 'uuid'::regtype)
         or (a.attname = 'not_after' and a.atttypid = 'timestamptz'::regtype))) <> 3 then
    raise exception 'SESSION_VERDICT_PRECONDITION_SESSIONS_SHAPE';
  end if;
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'SESSION_VERDICT_PRECONDITION_%', private.account_lifecycle_owner_epoch_exposure();
  end if;
end $$;

-- SV: the session-only verdict.
create function private.account_lifecycle_session_verdict()
returns text language plpgsql stable security definer set search_path = '' set row_security = off as $$
declare
  v_claims jsonb;
  v_sub text;
  v_role text;
  v_session text;
  v_anonymous text;
  v_user uuid;
  v_session_id uuid;
  f_user_exists boolean;
  f_session_state text;
begin
  -- 1. the subject: the request's JWT only, exactly as R1 (settings and auth.uid() only; no row is read)
  v_sub := nullif(pg_catalog.current_setting('request.jwt.claim.sub', true), '');
  if v_sub is not null then
    v_role := nullif(pg_catalog.current_setting('request.jwt.claim.role', true), '');
    v_session := nullif(pg_catalog.current_setting('request.jwt.claim.session_id', true), '');
    v_anonymous := coalesce(nullif(pg_catalog.current_setting('request.jwt.claim.is_anonymous', true), ''), 'false');
  else
    begin
      v_claims := nullif(pg_catalog.current_setting('request.jwt.claims', true), '')::jsonb;
    exception when others then
      v_claims := null;
    end;
    if pg_catalog.jsonb_typeof(v_claims) = 'object' then
      v_sub := v_claims ->> 'sub';
      v_role := v_claims ->> 'role';
      v_session := v_claims ->> 'session_id';
      v_anonymous := coalesce(nullif((v_claims -> 'is_anonymous')::text, 'null'), 'false');
    end if;
  end if;
  if v_sub ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' and v_session ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and v_role = 'authenticated' and v_anonymous = 'false' then
    if (select auth.uid()) is not distinct from v_sub::uuid then
      v_user := v_sub::uuid;
      v_session_id := v_session::uuid;
    end if;
  end if;
  if v_user is null then
    return 'AUTH_REQUIRED';
  end if;

  -- 2. the login and the session, in ONE statement: the row by id AND user_id (another person's session is no session), not_after in the future
  select exists (select 1 from auth.users u where u.id = v_user),
         (select case when s.id is null then 'revoked'
                      when s.not_after is null or s.not_after > pg_catalog.clock_timestamp() then 'active' else 'expired' end
            from (select 1) x left join auth.sessions s on s.id = v_session_id and s.user_id = v_user)
    into f_user_exists, f_session_state;

  if not f_user_exists then
    return 'AUTH_REQUIRED';
  end if;
  return case f_session_state when 'active' then 'active' when 'revoked' then 'SESSION_REVOKED' when 'expired' then 'SESSION_EXPIRED' end;
end $$;

revoke all on function private.account_lifecycle_session_verdict() from public, anon, authenticated, service_role;

-- Postconditions: the exact ACL (the owner only), the shape, and the role graph: no API role is a MEMBER (direct or indirect, INHERIT or not, SET or
-- not) of a role that may EXECUTE it, and no non-superuser role but the owner's own may.
do $$
declare
  v_owner text := quote_ident(current_user);
  v_sv regprocedure := 'private.account_lifecycle_session_verdict()'::regprocedure;
begin
  if (select array_to_string(p.proacl::text[], ',') from pg_catalog.pg_proc p where p.oid = v_sv) is distinct from format('%s=X/%s', v_owner, v_owner) then
    raise exception 'SESSION_VERDICT_POSTCONDITION_ACL';
  end if;
  if not exists (select 1 from pg_catalog.pg_proc p where p.oid = v_sv and p.provolatile = 's' and p.prosecdef
                  and p.proconfig @> array['search_path=""', 'row_security=off'] and p.pronargs = 0
                  and p.proowner = (select r.oid from pg_catalog.pg_roles r where r.rolname = current_user)) then
    raise exception 'SESSION_VERDICT_POSTCONDITION_SHAPE';
  end if;
  if exists (select 1 from pg_catalog.pg_roles a join pg_catalog.pg_roles r on pg_catalog.pg_has_role(a.oid, r.oid, 'MEMBER')
              where a.rolname in ('anon', 'authenticated', 'service_role', 'authenticator') and pg_catalog.has_function_privilege(r.oid, v_sv, 'EXECUTE')) then
    raise exception 'SESSION_VERDICT_POSTCONDITION_API_ROLE_REACHES';
  end if;
  if exists (select 1 from pg_catalog.pg_roles r
              where not r.rolsuper and pg_catalog.has_function_privilege(r.oid, v_sv, 'EXECUTE')
                and not pg_catalog.pg_has_role(r.oid, (select o.oid from pg_catalog.pg_roles o where o.rolname = current_user), 'USAGE')) then
    raise exception 'SESSION_VERDICT_POSTCONDITION_OTHER_ROLE_EXECUTES';
  end if;
  if private.account_lifecycle_owner_epoch_exposure() is not null then
    raise exception 'SESSION_VERDICT_POSTCONDITION_EXPOSURE';
  end if;
end $$;


